#include "sector_relation_page.hpp"
#include "research_companies_page.hpp"
#include <QtWidgets>
SectorRelationPage::SectorRelationPage(QString report,QString research,std::shared_ptr<BusinessStore> b,QWidget* parent):QWidget(parent),store(research,b->filePath()),business(b),reportId(report){
 setObjectName("sectorRelationPage");auto root=new QVBoxLayout(this);status=new QLabel("请明确选择已有产业主题，阅读逐条差异和完整来源后复核。",this);status->setWordWrap(true);status->setObjectName("sectorRelationStatus");root->addWidget(status);
 pages=new QStackedWidget(this);root->addWidget(pages,1);review=new QWidget(pages);pages->addWidget(review);auto layout=new QVBoxLayout(review);topics=new QComboBox(review);topics->setObjectName("sectorRelationTopic");topics->addItem("请选择已有产业主题","");for(auto v:store.topics()){auto t=v.toObject();topics->addItem(t["name"].toString()+" / "+t["id"].toString(),t["id"].toString());}layout->addWidget(topics);
 auto actions=new QGridLayout;layout->addLayout(actions);int count=0;auto button=[&](QString name,QString label,std::function<void()> fn){auto w=new QPushButton(label,review);w->setObjectName(name);actions->addWidget(w,count/3,count%3);++count;connect(w,&QPushButton::clicked,this,[=]{if(!live()||pages->currentWidget()!=review)return;try{fn();}catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}});};
 auto tabs=new QTabWidget(review);layout->addWidget(tabs,1);decisions=new QTableWidget(0,2,tabs);decisions->setObjectName("sectorRelationDecisions");decisions->setHorizontalHeaderLabels({"原文关系与差异","明确复核动作"});decisions->horizontalHeader()->setSectionResizeMode(0,QHeaderView::Stretch);decisions->horizontalHeader()->setSectionResizeMode(1,QHeaderView::ResizeToContents);decisions->setEditTriggers(QAbstractItemView::NoEditTriggers);tabs->addTab(decisions,"逐条复核");reader=new QPlainTextEdit(tabs);reader->setReadOnly(true);reader->setObjectName("sectorRelationOriginal");tabs->addTab(reader,"差异与完整原件");
 note=new QPlainTextEdit(review);note->setObjectName("sectorRelationNote");note->setPlaceholderText("人工复核说明（必填）；人工核验只针对原文关系，不证明证券身份或事实真实性");note->setMaximumHeight(72);layout->addWidget(note);consent=new QCheckBox("已逐条阅读并选择；确认追加复核版本及所选关系",review);consent->setObjectName("sectorRelationConsent");layout->addWidget(consent);
 history=new QComboBox(review);history->setObjectName("sectorRelationHistory");layout->addWidget(history);graphRows=new QComboBox(review);graphRows->setObjectName("sectorRelationGraphRows");layout->addWidget(graphRows);
 button("sectorRelationPreview","重新读取并预览差异",[=]{cancel();viewed={};graphRows->clear();auto topic=topics->currentData().toString();business::require(!topic.isEmpty(),"请明确选择已有产业主题");pending=store.preview(reportId,topic);reader->setPlainText(sectorRelation::read(pending));auto rows=pending["rows"].toArray();decisions->setRowCount(rows.size());for(int i=0;i<rows.size();++i){auto row=rows[i].toObject(),proposal=row["proposal"].toObject();QString type=row["change"].toString();static const QMap<QString,QString> labels={{"new","新关系"},{"additional-evidence","已有关系的新证据"},{"duplicate","完全重复，保留旧人工关系"},{"conflict","存在相反观点，仅可待复核"},{"source-unmapped","来源未入资料正文，不能写入关系"}};auto item=new QTableWidgetItem(labels.value(type,type)+"\n"+proposal["companyName"].toString()+" / "+proposal["product"].toString()+"\n"+proposal["claim"].toString()+"\n引用："+proposal["quote"].toString());decisions->setItem(i,0,item);auto choice=new QComboBox(decisions);choice->addItem("请选择动作","");choice->addItem("跳过","skip");if(!row["flags"].toArray().contains("source-unmapped"))choice->addItem("保留待核验 / 记录重复","candidate");if(row["canVerify"].toBool())choice->addItem("原文关系人工核验","verify");decisions->setCellWidget(i,1,choice);connect(choice,qOverload<int>(&QComboBox::currentIndexChanged),this,[=]{consent->setChecked(false);});}decisions->resizeRowsToContents();tabs->setCurrentWidget(decisions);status->setText(rows.isEmpty()?"该报告没有关系可复核；完整报告仍可阅读。":"差异已读取；每行均需明确选择，尚未保存。");refreshHistory();});
 button("sectorRelationSave","确认追加复核版本",[=]{business::require(!pending.isEmpty()&&consent->isChecked(),"请先预览、逐条选择并确认");QJsonArray choices;for(int i=0;i<decisions->rowCount();++i)choices.append(qobject_cast<QComboBox*>(decisions->cellWidget(i,1))->currentData().toString());auto version=sectorRelation::version(pending,choices,note->toPlainText(),QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));auto ticket=epoch;store.save(version,[=]{return epoch!=ticket||!live();});cancel();readVersion(version);refreshHistory();status->setText("已追加复核版本。旧人工关系保持；可打开原有关系图与原文。");});
 button("sectorRelationCancel","取消本次复核",[=]{cancel();status->setText("本次保存资格已取消，历史与原关系保留。");});
 button("sectorRelationReadHistory","阅读所选复核版本",[=]{auto id=history->currentData().toString();business::require(!id.isEmpty(),"请选择复核历史");auto v=store.readVersion(id);cancel();readVersion(v);tabs->setCurrentWidget(reader);});
 button("sectorRelationGraph","打开既有关系图 / 原文",[=]{openGraph();});
 button("sectorRelationBack","返回报告历史",[=]{cancel();if(onBack)onBack();});
 connect(topics,qOverload<int>(&QComboBox::currentIndexChanged),this,[=]{cancel();viewed={};graphRows->clear();reader->clear();try{refreshHistory();}catch(const std::exception&e){status->setText(e.what());}});
 connect(note,&QPlainTextEdit::textChanged,this,[=]{consent->setChecked(false);});connect(qApp,&QGuiApplication::applicationStateChanged,this,[=](Qt::ApplicationState s){if(s!=Qt::ApplicationActive)cancel();});
}
bool SectorRelationPage::live()const{return isVisible()&&window()->isVisible()&&!window()->isMinimized()&&QGuiApplication::applicationState()==Qt::ApplicationActive;}
void SectorRelationPage::cancel(){++epoch;pending={};if(consent)consent->setChecked(false);if(decisions)decisions->setRowCount(0);}
void SectorRelationPage::hideEvent(QHideEvent* e){cancel();QWidget::hideEvent(e);}
void SectorRelationPage::refreshHistory(){QSignalBlocker block(history);history->clear();auto topic=topics->currentData().toString();if(topic.isEmpty())return;for(auto id:store.versions(topic))history->addItem(id,id);}
void SectorRelationPage::readVersion(const QJsonObject& v){viewed=v;reader->setPlainText(sectorRelation::read(v["preview"].toObject())+"\n复核版本完整原件：\n"+QString::fromUtf8(QJsonDocument(v).toJson()));graphRows->clear();QSet<QString> seen;for(auto value:v["inserts"].toArray()){auto r=value.toObject();auto id=r["id"].toString();seen.insert(id);graphRows->addItem(r["claim"].toString()+" / "+id,id);}for(auto value:v["preview"].toObject()["rows"].toArray())for(auto id:value.toObject()["existingIds"].toArray())if(!seen.contains(id.toString())){seen.insert(id.toString());graphRows->addItem("既有关系 / "+id.toString(),id.toString());}if(auto tabs=review->findChild<QTabWidget*>())tabs->setCurrentWidget(reader);}
void SectorRelationPage::openGraph(){business::require(!viewed.isEmpty()&&!graphRows->currentData().toString().isEmpty(),"先阅读已保存版本并选择其中的关系");cancel();if(graph){auto old=graph->parentWidget();pages->removeWidget(old);old->deleteLater();graph=nullptr;}auto pane=new QWidget(pages);auto l=new QVBoxLayout(pane);auto back=new QPushButton("返回复核版本",pane);l->addWidget(back);graph=new ResearchCompaniesPage(business,pane);l->addWidget(graph,1);pages->addWidget(pane);connect(back,&QPushButton::clicked,this,[=]{pages->setCurrentWidget(review);});graph->openGraphRelation(viewed["topicId"].toString(),graphRows->currentData().toString());pages->setCurrentWidget(pane);}
